import{_ as r,C as e,o as n,c as s,a2 as a,E as i}from"./chunks/framework.wVcpyw2-.js";const f=JSON.parse('{"title":"表单/服务组件","description":"灵萌 UI 编辑器服务表单页 16 个表单组件：输入、选项、地址、费用展示与提交底栏配置手册。","frontmatter":{"title":"表单/服务组件","description":"灵萌 UI 编辑器服务表单页 16 个表单组件：输入、选项、地址、费用展示与提交底栏配置手册。"},"headers":[],"relativePath":"features/ui-editor/components-form.md","filePath":"features/ui-editor/components-form.md","lastUpdated":1787335593000}'),l={name:"features/ui-editor/components-form.md"};function c(p,t,d,g,_,m){const o=e("DocOverview");return n(),s("div",null,[t[0]||(t[0]=a('<h1 id="表单-服务组件" tabindex="-1">表单 / 服务组件 <a class="header-anchor" href="#表单-服务组件" aria-label="Permalink to &quot;表单 / 服务组件&quot;">​</a></h1><p>本文档面向 <strong>服务表单（errand_service）</strong> 页面的 <strong>16 个表单组件</strong>。<br><strong>价格怎么算</strong>：先在各组件属性里配「计价」形成项目加价，再在页面级「服务表单」Tab → <strong>配置计价方式</strong> 选择如何把基础价、项目加价、配送费相加（详见下方「表单价格怎么算」）。</p><h2 id="条件显隐" tabindex="-1">条件显隐 <a class="header-anchor" href="#条件显隐" aria-label="Permalink to &quot;条件显隐&quot;">​</a></h2><p>在组件属性面板的 <strong>条件显隐</strong> 分组中，可为任意表单组件（含分割线/说明）配置显示规则：</p><ul><li><strong>来源字段</strong>：只能选当前组件<strong>之前</strong>的画布字段，不能引用自身或后面的组件</li><li><strong>匹配方式</strong>：全部满足 / 任一满足</li><li><strong>运算符</strong>：等于、为空、开关开/关、多选包含、数字比较等</li><li><strong>隐藏语义</strong>：不渲染、不校验必填、不计价、不进提交 payload，并清空已填值</li></ul><p>保存模板时会自动校验 <strong>循环依赖</strong> 与 <strong>前向引用</strong>；启用规则的组件在画布右上角显示「条件」角标。页面级「服务表单」Tab 会统计启用数量。</p>',6)),i(o,{page:"ui-editor-components-form"})])}const h=r(l,[["render",c]]);export{f as __pageData,h as default};
